void Compute(OpKernelContext* context) override {
  const Tensor& x = context->input(0);
  const Tensor& y = context->input(1);
  const float min_x = context->input(2).flat<float>()(0);
  const float max_x = context->input(3).flat<float>()(0);
  const float min_y = context->input(4).flat<float>()(0);
  const float max_y = context->input(5).flat<float>()(0);

  BCast bcast(BCast::FromShape(x.shape()), BCast::FromShape(y.shape()));
  if (!bcast.IsValid()) {
    context->SetStatus(errors::InvalidArgument(
        "Incompatible shapes: ", x.shape().DebugString(), " vs. ",
        y.shape().DebugString()));
    return;
  }
  Tensor* z;
  OP_REQUIRES_OK(context, context->allocate_output(
                              0, BCast::ToShape(bcast.output_shape()), &z));

  // Make sure that we have valid quantization ranges for the input buffers.
  // If the difference between the min and max is negative or zero, it makes
  // it hard to do meaningful intermediate operations on the values.
  OP_REQUIRES(context, (max_x > min_x),
              errors::InvalidArgument("max_x must be larger than min_a."));
  OP_REQUIRES(context, (max_y > min_y),
              errors::InvalidArgument("max_x must be larger than min_b."));
  const int32 offset_x = FloatToQuantizedUnclamped<T>(0.0f, min_x, max_x);
  const int32 offset_y = FloatToQuantizedUnclamped<T>(0.0f, min_y, max_y);
  const T* x_data = x.flat<T>().data();
  const T* y_data = y.flat<T>().data();
  Toutput* z_data = z->flat<Toutput>().data();

  const int ndims = bcast.x_reshape().size();
  if (ndims <= 1) {
    if (x.NumElements() == 1) {
      ScalarMultiply<T, Toutput>(context, y_data, offset_y, y.NumElements(),
                                 x_data[0], offset_x, z_data);
    } else if (y.NumElements() == 1) {
      ScalarMultiply<T, Toutput>(context, x_data, offset_x, x.NumElements(),
                                 y_data[0], offset_y, z_data);
    } else {
      VectorMultiply<T, Toutput>(context, x_data, offset_x, y_data, offset_y,
                                 x.NumElements(), z_data);
    }
  } else if (ndims == 2) {
    const T* vector_data;
    int64 vector_num_elements;
    int32 vector_offset;
    const T* tensor_data;
    int64 tensor_num_elements;
    int32 tensor_offset;
    if (x.NumElements() < y.NumElements()) {
      vector_data = x_data;
      vector_num_elements = x.NumElements();
      vector_offset = offset_x;
      tensor_data = y_data;
      tensor_num_elements = y.NumElements();
      tensor_offset = offset_y;
    } else {
      vector_data = y_data;
      vector_num_elements = y.NumElements();
      vector_offset = offset_y;
      tensor_data = x_data;
      tensor_num_elements = x.NumElements();
      tensor_offset = offset_x;
    }
    VectorTensorMultiply<T, Toutput>(
        vector_data, vector_offset, vector_num_elements, tensor_data,
        tensor_offset, tensor_num_elements, z_data);
  } else {
    LOG(INFO) << "ndims=" << ndims;
    LOG(INFO) << "bcast.x_reshape()="
              << TensorShape(bcast.x_reshape()).DebugString();
    LOG(INFO) << "bcast.y_reshape()="
              << TensorShape(bcast.y_reshape()).DebugString();
    LOG(INFO) << "bcast.x_bcast()="
              << TensorShape(bcast.x_bcast()).DebugString();
    LOG(INFO) << "bcast.y_bcast()="
              << TensorShape(bcast.y_bcast()).DebugString();

    context->SetStatus(errors::Unimplemented(
        "Broadcast between ", context->input(0).shape().DebugString(),
        " and ", context->input(1).shape().DebugString(),
        " is not supported yet."));
    return;
  }

  float min_z_value;
  float max_z_value;
  QuantizationRangeForMultiplication<T, T, Toutput>(
      min_x, max_x, min_y, max_y, &min_z_value, &max_z_value);
  Tensor* z_min = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(1, {}, &z_min));
  z_min->flat<float>()(0) = min_z_value;

  Tensor* z_max = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(2, {}, &z_max));
  z_max->flat<float>()(0) = max_z_value;
}

htmlParseNameComplex(xmlParserCtxtPtr ctxt) {
    int len = 0, l;
    int c;
    int count = 0;

    /*
     * Handler for more complex cases
     */
    GROW;
    c = CUR_CHAR(l);
    if ((c == ' ') || (c == '>') || (c == '/') || /* accelerators */
	(!IS_LETTER(c) && (c != '_') &&
         (c != ':'))) {
	return(NULL);
    }

    while ((c != ' ') && (c != '>') && (c != '/') && /* test bigname.xml */
	   ((IS_LETTER(c)) || (IS_DIGIT(c)) ||
            (c == '.') || (c == '-') ||
	    (c == '_') || (c == ':') ||
	    (IS_COMBINING(c)) ||
	    (IS_EXTENDER(c)))) {
	if (count++ > 100) {
	    count = 0;
	    GROW;
	}
	len += l;
	NEXTL(l);
	c = CUR_CHAR(l);
    }
    return(xmlDictLookup(ctxt->dict, ctxt->input->cur - len, len));
}

bool AES_GCM_DecryptContext::Decrypt(
	const void *pEncryptedDataAndTag, size_t cbEncryptedDataAndTag,
	const void *pIV,
	void *pPlaintextData, uint32 *pcbPlaintextData,
	const void *pAdditionalAuthenticationData, size_t cbAuthenticationData
) {
    unsigned long long pcbPlaintextData_longlong;

    const int nDecryptResult = crypto_aead_aes256gcm_decrypt_afternm(
		static_cast<unsigned char*>( pPlaintextData ), &pcbPlaintextData_longlong,
		nullptr,
		static_cast<const unsigned char*>( pEncryptedDataAndTag ), cbEncryptedDataAndTag,
		static_cast<const unsigned char*>( pAdditionalAuthenticationData ), cbAuthenticationData,
		static_cast<const unsigned char*>( pIV ), static_cast<const crypto_aead_aes256gcm_state*>( m_ctx )
	);

    *pcbPlaintextData = pcbPlaintextData_longlong;

    return nDecryptResult == 0;
}

static Quantum ApplyFunction(Quantum pixel,const MagickFunction function,
  const size_t number_parameters,const double *parameters,
  ExceptionInfo *exception)
{
  MagickRealType
    result;

  ssize_t
    i;

  (void) exception;
  result=0.0;
  switch (function)
  {
    case PolynomialFunction:
    {
      /*
       * Polynomial
       * Parameters:   polynomial constants,  highest to lowest order
       *   For example:      c0*x^3 + c1*x^2 + c2*x  + c3
       */
      result=0.0;
      for (i=0; i < (ssize_t) number_parameters; i++)
        result=result*QuantumScale*pixel + parameters[i];
      result*=QuantumRange;
      break;
    }
    case SinusoidFunction:
    {
      /* Sinusoid Function
       * Parameters:   Freq, Phase, Ampl, bias
       */
      double  freq,phase,ampl,bias;
      freq  = ( number_parameters >= 1 ) ? parameters[0] : 1.0;
      phase = ( number_parameters >= 2 ) ? parameters[1] : 0.0;
      ampl  = ( number_parameters >= 3 ) ? parameters[2] : 0.5;
      bias  = ( number_parameters >= 4 ) ? parameters[3] : 0.5;
      result=(MagickRealType) (QuantumRange*(ampl*sin((double) (2.0*MagickPI*
        (freq*QuantumScale*pixel + phase/360.0) )) + bias ) );
      break;
    }
    case ArcsinFunction:
    {
      /* Arcsin Function  (peged at range limits for invalid results)
       * Parameters:   Width, Center, Range, Bias
       */
      double  width,range,center,bias;
      width  = ( number_parameters >= 1 ) ? parameters[0] : 1.0;
      center = ( number_parameters >= 2 ) ? parameters[1] : 0.5;
      range  = ( number_parameters >= 3 ) ? parameters[2] : 1.0;
      bias   = ( number_parameters >= 4 ) ? parameters[3] : 0.5;
      result = 2.0/width*(QuantumScale*pixel - center);
      if ( result <= -1.0 )
        result = bias - range/2.0;
      else if ( result >= 1.0 )
        result = bias + range/2.0;
      else
        result=(MagickRealType) (range/MagickPI*asin((double) result)+bias);
      result *= QuantumRange;
      break;
    }
    case ArctanFunction:
    {
      /* Arctan Function
       * Parameters:   Slope, Center, Range, Bias
       */
      double  slope,range,center,bias;
      slope  = ( number_parameters >= 1 ) ? parameters[0] : 1.0;
      center = ( number_parameters >= 2 ) ? parameters[1] : 0.5;
      range  = ( number_parameters >= 3 ) ? parameters[2] : 1.0;
      bias   = ( number_parameters >= 4 ) ? parameters[3] : 0.5;
      result=(MagickRealType) (MagickPI*slope*(QuantumScale*pixel-center));
      result=(MagickRealType) (QuantumRange*(range/MagickPI*atan((double)
                  result) + bias ) );
      break;
    }
    case UndefinedFunction:
      break;
  }
  return(ClampToQuantum(result));
}

static void hid_input_field(struct hid_device *hid, struct hid_field *field,
			    __u8 *data, int interrupt)
{
	unsigned n;
	unsigned count = field->report_count;
	unsigned offset = field->report_offset;
	unsigned size = field->report_size;
	__s32 min = field->logical_minimum;
	__s32 max = field->logical_maximum;
	__s32 *value;

	value = kmalloc(sizeof(__s32) * count, GFP_ATOMIC);
	if (!value)
		return;

	for (n = 0; n < count; n++) {

		value[n] = min < 0 ?
			snto32(hid_field_extract(hid, data, offset + n * size,
			       size), size) :
			hid_field_extract(hid, data, offset + n * size, size);

		/* Ignore report if ErrorRollOver */
		if (!(field->flags & HID_MAIN_ITEM_VARIABLE) &&
		    value[n] >= min && value[n] <= max &&
		    field->usage[value[n] - min].hid == HID_UP_KEYBOARD + 1)
			goto exit;
	}

	for (n = 0; n < count; n++) {

		if (HID_MAIN_ITEM_VARIABLE & field->flags) {
			hid_process_event(hid, field, &field->usage[n], value[n], interrupt);
			continue;
		}

		if (field->value[n] >= min && field->value[n] <= max
			&& field->usage[field->value[n] - min].hid
			&& search(value, field->value[n], count))
				hid_process_event(hid, field, &field->usage[field->value[n] - min], 0, interrupt);

		if (value[n] >= min && value[n] <= max
			&& field->usage[value[n] - min].hid
			&& search(field->value, value[n], count))
				hid_process_event(hid, field, &field->usage[value[n] - min], 1, interrupt);
	}

	memcpy(field->value, value, count * sizeof(__s32));
exit:
	kfree(value);
}

static void cn_proc_mcast_ctl(struct cn_msg *msg,
			      struct netlink_skb_parms *nsp)
{
	enum proc_cn_mcast_op *mc_op = NULL;
	int err = 0;

	if (msg->len != sizeof(*mc_op))
		return;

	/* 
	 * Events are reported with respect to the initial pid
	 * and user namespaces so ignore requestors from
	 * other namespaces.
	 */
	if ((current_user_ns() != &init_user_ns) ||
	    (task_active_pid_ns(current) != &init_pid_ns))
		return;

	/* Can only change if privileged. */
	if (!capable(CAP_NET_ADMIN)) {
		err = EPERM;
		goto out;
	}

	mc_op = (enum proc_cn_mcast_op *)msg->data;
	switch (*mc_op) {
	case PROC_CN_MCAST_LISTEN:
		atomic_inc(&proc_event_num_listeners);
		break;
	case PROC_CN_MCAST_IGNORE:
		atomic_dec(&proc_event_num_listeners);
		break;
	default:
		err = EINVAL;
		break;
	}

out:
	cn_proc_ack(err, msg->seq, msg->ack);
}

